        "testata": "The Hill",
        "lingua_originale": "en",
        "titolo_orig": "Dem rep dismisses Fetterman saying some in party 'cheering' for Iran",
        "testo_it": "Rep. Dem USA smentisce Fetterman: \"Nessuno nel partito tifa per l'Iran\".",
        "priorita": "Media",
        "id_gruppo": 24,
